scripts.content:
/**
 * ============================================================================
 *  通用防截断 / 防空回传输层  (TavernHelper 酒馆助手脚本)
 * ============================================================================
 *
 *  原理：
 *    1. 拦截酒馆的生成请求 (fetch patch，仅匹配 /api/backends/<渠道>/generate)
 *    2. 往请求里注入一个随机命名的"传输函数"，并附一条控制指令：
 *       要求模型把完整回复写进该函数调用的 content 参数
 *    3. 在响应流里实时把函数参数文本还原成普通 assistant 正文，
 *       并抹掉工具调用痕迹——前端从头到尾看到的就是一条正常的流式回复
 *
 *  效果：正文藏在结构化参数里传输，绕过渠道对普通正文的截断/过滤/空回。
 *
 *  使用：
 *    - 酒馆助手新建脚本，粘贴本文件，启用
 *    - 聊天界面底部出现「🛡 防截断」脚本按钮：点击开关
 *    - 「🧪 防截断自检」按钮：一键回环测试改写链路（假上游，不消耗 token）
 *    - 页面右下角小指示牌实时显示状态（点击也可开关）
 *
 *  要求：模型/渠道支持函数调用 (function calling)。连续多次拿不到正文时
 *  会弹提示——那多半是渠道不支持函数调用，关掉即可，不影响正常使用。
 * ============================================================================
 */
(function () {
  "use strict";

  // ==========================================================================
  // 配置（想调的人改这里）
  // ==========================================================================
  const CONFIG = {
    /** 只拦截酒馆的生成接口 */
    endpoint: /\/api\/backends\/[^/]+\/generate\b/,
    /** 传输函数名前缀，每次请求拼上 24 位随机 hex，防渠道按名字识别 */
    toolPrefix: "emit_complete_response_",
    /** 传输函数的描述（模型看得） */
    toolDescription:
      "Emit the complete final user-visible reply exactly once. Put the entire reply in the content argument and write no reply text outside this call.",
    /** 控制指令（模型看得）。{name} 会被替换成当次的函数名 */
    controlPrompt: (name) =>
      `Call the \`${name}\` function exactly once and put your complete final reply in its \`content\` argument. ` +
      `Do not write any of the final reply outside that call. Use any other available tools normally when they are needed.`,
    /** 连续多少次没从传输函数拿到正文后提示"渠道可能不支持" */
    softMissLimit: 3,
    /** 开关存储键（酒馆助手脚本变量 / localStorage） */
    storageKey: "universalAntiTruncation",
    /** 酒馆助手脚本按钮名 */
    buttonName: "🛡 防截断",
    /** 自检按钮名 */
    testButtonName: "🧪 防截断自检",
    /** 日志前缀 */
    logPrefix: "[防截断]",
    /** 状态指示牌位置 */
    indicator: { bottom: "12px", right: "12px" },
  };

  const MARKER = "__antiTruncationFetchPatch__";

  // ==========================================================================
  // 日志
  // ==========================================================================
  function log(level, message, detail) {
    const fn =
      level === "error" ? console.error : level === "warn" ? console.warn : console.info;
    if (detail === undefined) fn.call(console, `${CONFIG.logPrefix} ${message}`);
    else fn.call(console, `${CONFIG.logPrefix} ${message}`, detail);
  }

  function describeError(error) {
    return error instanceof Error ? `${error.name}: ${error.message}` : String(error);
  }

  // ==========================================================================
  // 运行状态（本次会话内存）
  // ==========================================================================
  const stats = {
    enabled: false,
    transported: 0, // 成功走传输函数
    plainReply: 0, // 模型没理睬，走了普通正文
    other: 0, // bypass / 非流式没找到调用 / 上游错误
    missStreak: 0, // 连续 plainReply 次数
    lastOutcome: "—",
    lastDetail: "",
  };

  // ==========================================================================
  // 持久化：酒馆助手脚本变量，失败退回 localStorage
  // ==========================================================================
  function loadEnabled() {
    try {
      if (typeof getVariables === "function") {
        const vars = getVariables({ type: "script" }) ?? {};
        if (typeof vars[CONFIG.storageKey] === "boolean") return vars[CONFIG.storageKey];
      }
    } catch { /* fallthrough */ }
    try {
      const raw = localStorage.getItem(CONFIG.storageKey);
      if (raw === "false") return false;
    } catch { /* ignore */ }
    return true; // 默认开
  }

  function saveEnabled(value) {
    try {
      if (typeof getVariables === "function" && typeof replaceVariables === "function") {
        const vars = getVariables({ type: "script" }) ?? {};
        vars[CONFIG.storageKey] = value;
        replaceVariables(vars, { type: "script" });
        return;
      }
    } catch { /* fallthrough */ }
    try {
      localStorage.setItem(CONFIG.storageKey, String(value));
    } catch { /* ignore */ }
  }

  // ==========================================================================
  // 通知（酒馆的 toastr，拿不到就算了）
  // ==========================================================================
  function toast(level, message) {
    try {
      const global = globalThis.toastr ?? window.parent?.toastr;
      if (global?.[level]) global[level](message, CONFIG.logPrefix.trim());
    } catch { /* ignore */ }
  }

  // ==========================================================================
  // 工具命名
  // ==========================================================================
  function randomToolName(existing) {
    for (let i = 0; i < 100; i++) {
      const bytes = new Uint8Array(12);
      crypto.getRandomValues(bytes);
      const name =
        CONFIG.toolPrefix +
        Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
      if (!existing.has(name)) return name;
    }
    throw new Error("无法生成唯一的传输函数名");
  }

  function collectToolNames(tools) {
    const names = new Set();
    if (!Array.isArray(tools)) return names;
    for (const tool of tools) {
      const name = tool?.function?.name;
      if (typeof name === "string" && name) names.add(name);
    }
    return names;
  }

  // ==========================================================================
  // 请求改写
  // ==========================================================================

  /**
   * 解析并改写请求体。
   * 返回 { kind: "bypass", reason } 或
   * { kind: "prepared", body, toolName, clientToolNames, streamRequested }
   */
  function prepareRequest(rawBody) {
    let body;
    try {
      body = JSON.parse(rawBody);
      if (!body || typeof body !== "object" || Array.isArray(body)) {
        return { kind: "bypass", reason: "请求体不是 JSON 对象" };
      }
    } catch {
      return { kind: "bypass", reason: "请求体不可解析" };
    }

    const messages = body.messages;
    if (!Array.isArray(messages) || messages.length === 0) {
      return { kind: "bypass", reason: "没有消息列表" };
    }

    // 调用方强制了工具（required / 指定函数）或禁了工具：不掺和
    const choice = body.tool_choice;
    if (choice === "none") return { kind: "bypass", reason: "调用方禁用了工具" };
    if (choice === "required" || (choice && typeof choice === "object")) {
      return { kind: "bypass", reason: "调用方强制了工具" };
    }

    const existingTools = Array.isArray(body.tools) ? [...body.tools] : [];
    // 防重复注入：链条里残留自己的旧包装层（重挂后可能出现"我们包我们"），
    // 或用户把本脚本装了两份时，第二个实例看到前缀直接放行
    if (existingTools.some((t) => (t?.function?.name ?? "").startsWith(CONFIG.toolPrefix))) {
      return { kind: "bypass", reason: "传输函数已注入过（链条里有另一个自己）" };
    }
    const clientToolNames = collectToolNames(existingTools);
    const toolName = randomToolName(clientToolNames);

    body.tools = [
      ...existingTools,
      {
        type: "function",
        function: {
          name: toolName,
          description: CONFIG.toolDescription,
          parameters: {
            type: "object",
            properties: {
              content: { type: "string", description: "The complete final reply shown to the user." },
            },
            required: ["content"],
          },
        },
      },
    ];
    body.tool_choice = "auto";

    // 控制指令追加在末尾：上一条是 assistant 就用 user，否则用 system
    const control = CONFIG.controlPrompt(toolName);
    const lastRole = messages[messages.length - 1]?.role;
    body.messages = [
      ...messages,
      { role: lastRole === "assistant" ? "user" : "system", content: control },
    ];

    return {
      kind: "prepared",
      body: JSON.stringify(body),
      toolName,
      clientToolNames,
      streamRequested: body.stream === true,
    };
  }

  // ==========================================================================
  // 增量参数解码器
  // ----------------------------------------------------------------------------
  // 传输函数的 arguments 在流里是 JSON 字符串碎片，例如：
  //   {"content":"第一章...
  //   ...结尾"}
  // 这个状态机增量扫描出 content 键对应的字符串值，边到边吐（正确处理
  // \" \\ \n \uXXXX 转义和代理对字符），不等整个 JSON 闭合。
  // ==========================================================================
  class ArgumentDecoder {
    constructor() {
      this.buf = "";
      this.scanFrom = 0;   // 还没定位到 "content" 键时，从这里继续找
      this.inValue = false; // 已定位，开始解码字符串值
      this.done = false;   // 遇到收尾引号
      this.pos = 0;
      this.pendingHigh = ""; // 悬空的高位代理
      this.emitted = 0;    // 已吐出的字符数
    }

    /** 喂入一段 arguments 碎片，返回这段里新解码出的正文文本 */
    feed(fragment) {
      if (this.done || typeof fragment !== "string" || fragment === "") return "";
      this.buf += fragment;
      if (!this.inValue && !this.locateKey()) return "";
      return this.decodeValue();
    }

    locateKey() {
      const KEY = '"content"';
      for (;;) {
        const i = this.buf.indexOf(KEY, this.scanFrom);
        if (i < 0) return false;
        let j = i + KEY.length;
        // 等 ":" 到了再说
        while (j < this.buf.length && /\s/.test(this.buf[j])) j++;
        if (j >= this.buf.length) return false;
        if (this.buf[j] !== ":") { this.scanFrom = i + KEY.length; continue; }
        j++;
        while (j < this.buf.length && /\s/.test(this.buf[j])) j++;
        if (j >= this.buf.length) return false;
        if (this.buf[j] !== '"') { this.scanFrom = i + KEY.length; continue; }
        this.inValue = true;
        this.pos = j + 1;
        return true;
      }
    }

    decodeValue() {
      let out = "";
      const b = this.buf;
      const ESCAPES = { n: "\n", t: "\t", r: "\r", b: "\b", f: "\f", '"': '"', "\\": "\\", "/": "/" };
      while (this.pos < b.length && !this.done) {
        const c = b[this.pos];
        if (c === "\\") {
          if (this.pos + 1 >= b.length) break; // 等转义符后的字符
          const e = b[this.pos + 1];
          if (e === "u") {
            if (this.pos + 6 > b.length) break; // 等 4 位 hex
            const hex = b.slice(this.pos + 2, this.pos + 6);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) { this.done = true; break; }
            out += String.fromCharCode(parseInt(hex, 16));
            this.pos += 6;
          } else {
            out += ESCAPES[e] !== undefined ? ESCAPES[e] : e;
            this.pos += 2;
          }
          continue;
        }
        if (c === '"') { this.done = true; this.pos++; break; }
        out += c;
        this.pos++;
      }

      // 代理对：单身高位代理先扣住，等低位搭档到了一起放行
      let emit = out;
      if (this.pendingHigh) {
        if (emit.length) {
          const code = emit.charCodeAt(0);
          emit = code >= 0xdc00 && code <= 0xdfff ? this.pendingHigh + emit : emit;
          this.pendingHigh = "";
        } else {
          return "";
        }
      } else if (emit.length && !this.done) {
        const code = emit.charCodeAt(emit.length - 1);
        if (code >= 0xd800 && code <= 0xdbff) {
          this.pendingHigh = emit[emit.length - 1];
          emit = emit.slice(0, -1);
        }
      }
      this.emitted += emit.length;
      return emit;
    }
  }

  // ==========================================================================
  // 响应负载改写（OpenAI 格式 + Google 格式，流式与非流式共用）
  // ==========================================================================

  /**
   * 一个流的生命周期状态。每条流一个实例。
   * 冲突仲裁：谁先出现谁赢——模型先写了普通正文，传输函数的调用被丢弃；
   * 先开始函数调用，之后的普通正文 delta 被丢弃。
   */
  class RewriteContext {
    constructor(toolName, clientToolNames) {
      this.toolName = toolName;
      this.clientToolNames = clientToolNames;
      this.decoder = new ArgumentDecoder();
      this.matchedIndexes = new Set(); // OpenAI 流里已确认是"我们的"tool_calls index
      this.transportStarted = false;   // 开始从函数参数里吐正文
      this.plainSeen = false;          // 见到过普通正文
      this.suppressedOurs = false;     // 因正文优先而丢弃过传输函数调用
    }

    get stats() {
      return {
        syntheticSeen: this.transportStarted,
        decodedChars: this.decoder.emitted,
        contentConflict: this.transportStarted && this.plainSeen,
      };
    }

    /** 就地改写一个流式/非流式负载对象。返回是否有变化。 */
    rewriteChunk(obj) {
      let changed = false;
      if (obj && Array.isArray(obj.choices)) {
        for (const choice of obj.choices) changed = this.rewriteChoice(choice) || changed;
      }
      if (obj && Array.isArray(obj.candidates)) {
        for (const candidate of obj.candidates) changed = this.rewriteCandidate(candidate) || changed;
      }
      return changed;
    }

    rewriteChoice(choice) {
      if (!choice || typeof choice !== "object") return false;
      let changed = false;
      if (choice.delta) changed = this.rewriteDelta(choice.delta) || changed;
      if (choice.message) changed = this.rewriteMessage(choice.message) || changed;
      // 收尾：正文走了函数参数或函数调用被丢弃，都按普通 stop 结束
      if (choice.finish_reason === "tool_calls" && (this.transportStarted || this.suppressedOurs)) {
        choice.finish_reason = "stop";
        changed = true;
      }
      return changed;
    }

    rewriteDelta(delta) {
      let changed = false;

      if (typeof delta.content === "string" && delta.content.length > 0) {
        if (this.transportStarted) { delta.content = ""; changed = true; } // 函数赢了，丢弃正文
        else this.plainSeen = true;
      }

      if (Array.isArray(delta.tool_calls)) {
        const kept = [];
        for (const call of delta.tool_calls) {
          if (this.isOurs(call)) {
            changed = true;
            if (this.plainSeen) { this.suppressedOurs = true; continue; } // 正文赢了，丢弃函数调用
            this.transportStarted = true;
            if (typeof call.index === "number") this.matchedIndexes.add(call.index);
            if (call.id) this.matchedIndexes.add(call.id);
            const fragment = call.function?.arguments;
            if (typeof fragment === "string" && fragment) {
              const text = this.decoder.feed(fragment);
              if (text) delta.content = (delta.content ?? "") + text;
            }
          } else {
            kept.push(call); // 客户端自己的工具，原样保留
          }
        }
        if (kept.length !== delta.tool_calls.length) {
          if (kept.length === 0) delete delta.tool_calls;
          else delta.tool_calls = kept;
        }
      }
      return changed;
    }

    rewriteMessage(message) {
      if (!message || typeof message !== "object") return false;
      let changed = false;

      if (typeof message.content === "string" && message.content.length > 0) this.plainSeen = true;

      if (Array.isArray(message.tool_calls)) {
        const kept = [];
        for (const call of message.tool_calls) {
          if (!this.isOurs(call)) {
            kept.push(call); // 客户端自己的工具，原样保留
            continue;
          }
          changed = true;
          if (this.plainSeen) { this.suppressedOurs = true; continue; } // 正文赢了，丢弃函数调用
          this.transportStarted = true;
          const args = call.function?.arguments;
          if (typeof args === "string" && args) {
            const text = this.decoder.feed(args);
            if (text) message.content = (message.content ?? "") + text;
          }
        }
        if (kept.length !== message.tool_calls.length) {
          if (kept.length === 0) delete message.tool_calls;
          else message.tool_calls = kept;
        }
      }
      return changed;
    }

    /** Google 流式格式：candidates[].content.parts[] */
    rewriteCandidate(candidate) {
      if (!candidate?.content?.parts || !Array.isArray(candidate.content.parts)) return false;
      let changed = false;
      const kept = [];
      for (const part of candidate.content.parts) {
        const call = part?.functionCall;
        if (call && call.name === this.toolName && !this.plainSeen) {
          changed = true;
          this.transportStarted = true;
          const content = call.args?.content;
          if (typeof content === "string" && content) {
            this.decoder.feed(content);
            kept.push({ text: content });
          }
        } else if (call && call.name === this.toolName && this.plainSeen) {
          changed = true; // 正文赢了，丢弃
          this.suppressedOurs = true;
        } else {
          kept.push(part);
        }
      }
      // 数量不变也要写回：functionCall → text 是 1 换 1
      if (changed) candidate.content.parts = kept;
      return changed;
    }

    isOurs(call) {
      const name = call?.function?.name;
      if (name === this.toolName) return true;
      // 首块带名字，后续块只带 index / id
      if (typeof call?.index === "number" && this.matchedIndexes.has(call.index)) return true;
      if (call?.id && this.matchedIndexes.has(call.id)) return true;
      return false;
    }
  }

  // ==========================================================================
  // 响应形态探测：偷读头几个字节判断 SSE / JSON 数组 / 单 JSON，再把读过的
  // 字节原样回放成一条新的流
  // ==========================================================================
  const SSE_HEAD = /^\s*(?:data:|event:|id:|retry:|:)/;
  const JSON_ARRAY_HEAD = /^\s*\[/;
  const SNIFF_CHARS = 8;

  async function sniffResponseShape(response, contentType) {
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    const consumed = [];
    let head = "";
    let ended = false;
    let readError;
    try {
      while (!ended && head.length < SNIFF_CHARS) {
        const { value, done } = await reader.read();
        if (done) { ended = true; break; }
        if (!value || value.length === 0) continue;
        consumed.push(value);
        head += decoder.decode(value, { stream: true });
      }
    } catch (error) {
      readError = error;
      ended = true;
    }
    const replay = new ReadableStream({
      start(controller) {
        for (const value of consumed) controller.enqueue(value);
        if (readError !== undefined) { controller.error(readError); return; }
        if (ended) controller.close();
      },
      async pull(controller) {
        const { value, done } = await reader.read();
        if (done) { controller.close(); return; }
        controller.enqueue(value);
      },
      cancel(reason) { void reader.cancel(reason); },
    });
    const shape = JSON_ARRAY_HEAD.test(head)
      ? "json-array"
      : SSE_HEAD.test(head) || contentType.includes("text/event-stream")
        ? "sse"
        : "json";
    return { shape, response: new Response(replay, responseInit(response)) };
  }

  function responseInit(response) {
    return { status: response.status, statusText: response.statusText, headers: response.headers };
  }

  // ==========================================================================
  // SSE 流重写
  // ==========================================================================
  function rewriteSseStream(response, toolName, clientToolNames, onFinish) {
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    const ctx = new RewriteContext(toolName, clientToolNames);
    let lineBuf = "";
    let finished = false;

    const finish = () => {
      if (finished) return;
      finished = true;
      onFinish?.(ctx.stats);
    };

    return new Response(
      new ReadableStream({
        async pull(controller) {
          try {
            for (;;) {
              // lineBuf 里攒着一条完整行才处理
              const nl = lineBuf.indexOf("\n");
              if (nl >= 0) {
                const line = lineBuf.slice(0, nl);
                lineBuf = lineBuf.slice(nl + 1);
                const out = processLine(line, ctx);
                if (out !== null) controller.enqueue(encoder.encode(out));
                continue;
              }
              const { value, done } = await reader.read();
              if (done) {
                if (lineBuf) {
                  const out = processLine(lineBuf, ctx);
                  if (out !== null) controller.enqueue(encoder.encode(out));
                  lineBuf = "";
                }
                finish();
                controller.close();
                return;
              }
              lineBuf += decoder.decode(value, { stream: true });
            }
          } catch (error) {
            finish();
            controller.error(error);
          }
        },
        cancel(reason) {
          finish();
          void reader.cancel(reason);
        },
      }),
      responseInit(response),
    );
  }

  /** 处理一条 SSE 行。返回要发出的行（含换行），null 表示吞掉 */
  function processLine(line, ctx) {
    const match = /^(\s*)data:(.*)$/.exec(line);
    if (!match) return line + "\n"; // event:/id:/注释/空行，原样放行
    const payload = match[2].trim();
    if (payload === "") return line + "\n";
    if (payload === "[DONE]") return line + "\n";
    let obj;
    try {
      obj = JSON.parse(payload);
    } catch {
      return line + "\n"; // 半截 JSON 或非 JSON，原样放行
    }
    if (!ctx.rewriteChunk(obj)) return line + "\n";
    return `${match[1]}data: ${JSON.stringify(obj)}\n`;
  }

  // ==========================================================================
  // 非流式（单 JSON）重写
  // ==========================================================================
  async function rewriteJsonResponse(response, toolName, clientToolNames) {
    const text = await response.text();
    let obj;
    try {
      obj = JSON.parse(text);
    } catch {
      return { response, recovered: undefined };
    }
    const ctx = new RewriteContext(toolName, clientToolNames);
    ctx.rewriteChunk(obj);
    if (!ctx.transportStarted) return { response, recovered: undefined };
    const init = responseInit(response);
    init.headers = new Headers(response.headers);
    init.headers.delete("content-length");
    return {
      response: new Response(JSON.stringify(obj), init),
      recovered: ctx.stats,
    };
  }

  // ==========================================================================
  // JSON 数组流 → SSE
  // 有些渠道请求了流式却回 `[{...},{...}]`。整个读进来，逐个元素改写后
  // 包装成标准 SSE 事件发给前端（内容正确，只是失去逐字流式）
  // ==========================================================================
  async function reframeJsonArray(response, toolName, clientToolNames, onFinish) {
    const text = await response.text();
    let arr;
    try {
      arr = JSON.parse(text);
    } catch {
      onFinish?.({ syntheticSeen: false, decodedChars: 0 });
      return response;
    }
    const ctx = new RewriteContext(toolName, clientToolNames);
    if (Array.isArray(arr)) {
      for (const element of arr) ctx.rewriteChunk(element);
    } else {
      ctx.rewriteChunk(arr);
      arr = [arr];
    }
    onFinish?.(ctx.stats);
    const events =
      arr.map((element) => `data: ${JSON.stringify(element)}\n\n`).join("") + "data: [DONE]\n\n";
    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode(events));
        controller.close();
      },
    });
    const init = responseInit(response);
    init.headers = new Headers(response.headers);
    init.headers.set("content-type", "text/event-stream");
    init.headers.delete("content-length");
    return new Response(stream, init);
  }

  // ==========================================================================
  // 请求体读写工具
  // ==========================================================================
  function resolveUrl(input) {
    try {
      if (typeof input === "string") return input;
      if (input instanceof URL) return input.href;
      if (input?.url) return input.url; // Request
    } catch { /* ignore */ }
    return undefined;
  }

  async function readRequestBody(args) {
    try {
      if (args[0] instanceof Request) return await args[0].text();
      const body = args[1]?.body;
      if (typeof body === "string") return body;
      if (body && typeof body === "object") return JSON.stringify(body);
      return undefined;
    } catch (error) {
      throw error;
    }
  }

  function withBody(args, bodyText) {
    if (args[0] instanceof Request) {
      const request = args[0];
      const patched = new Request(request, {
        body: bodyText,
        headers: withAdjustedLength(request.headers, bodyText),
      });
      return [patched];
    }
    const init = { ...(args[1] ?? {}) };
    init.body = bodyText;
    if (init.headers) init.headers = withAdjustedLength(new Headers(init.headers), bodyText);
    return [args[0], init];
  }

  function withAdjustedLength(headers, bodyText) {
    const patched = new Headers(headers);
    patched.set("content-length", String(new TextEncoder().encode(bodyText).length));
    return patched;
  }

  // ==========================================================================
  // 拦截器本体
  // ==========================================================================
  class AntiTruncationInterceptor {
    constructor() {
      this.enabled = false;
      this.installed = false;
      this.target = undefined;
      this.original = undefined;
    }

    setEnabled(enabled) {
      this.enabled = enabled;
      log("info", `传输层 ${enabled ? "启用" : "停用"}`);
    }

    install() {
      if (this.installed) return;
      let target;
      try {
        target = window.parent ?? window;
        if (typeof target.fetch !== "function") return;
      } catch {
        log("warn", "够不到父窗口，不安装");
        return;
      }
      const current = target.fetch;
      const original = current[MARKER]?.original ?? current; // 别人已 patch 过就垫在别人上面
      const self = this;
      const wrapper = function patchedFetch(...args) {
        if (!self.enabled) return original.apply(this, args);
        try {
          const url = resolveUrl(args[0]);
          if (url && CONFIG.endpoint.test(url)) return self.intercept(original, this, args);
        } catch (error) {
          log("warn", `拦截失败，原样放行：${describeError(error)}`);
        }
        return original.apply(this, args);
      };
      wrapper[MARKER] = { original };
      target.fetch = wrapper;
      this.original = original;
      this.target = target;
      this.installed = true;
      log("info", "拦截器已安装");
    }

    /**
     * 自愈式挂载检查：确认我们的包装函数还在 fetch 链的最上层。
     * 酒馆环境里常有别的东西（酒馆助手自身的请求拦截、其它脚本、旧版面板）
     * 在我们之后又包一层 fetch——链条往往还能用，但 MARKER 被盖住看不见了；
     * 也可能 iframe 被卸载重挂导致拦截器真的掉了。两种情况都重新挂到最上层。
     * 返回 "ok" 或描述修复结果/失败原因的字符串。
     */
    ensureInstalled() {
      let onTop = false;
      try { onTop = !!(this.target?.fetch?.[MARKER]); } catch { onTop = false; }
      if (this.installed && onTop) return "ok";
      const reason = this.installed ? "被其它脚本/扩展盖住了" : "拦截器不在位（可能被页面重挂过）";
      const wasEnabled = this.enabled; // dispose 会把 enabled 置 false，重挂后要恢复
      this.dispose();
      this.install();
      this.setEnabled(wasEnabled);
      let now = false;
      try { now = !!(this.target?.fetch?.[MARKER]); } catch { now = false; }
      const result = now ? `已自动重新挂载（${reason}）` : `重新挂载失败（${reason}）`;
      log(now ? "info" : "warn", result);
      return result;
    }

    dispose() {
      this.enabled = false;
      if (!this.installed || !this.target || !this.original) {
        this.installed = false;
        return;
      }
      const current = this.target.fetch;
      if (current && current[MARKER]) {
        this.target.fetch = this.original;
        log("info", "拦截器已卸载");
      } else {
        log("warn", "有别的 patch 叠在上面，保持链条不动");
      }
      this.installed = false;
      this.target = undefined;
      this.original = undefined;
    }

    async intercept(original, thisArg, args) {
      const passthrough = () => original.apply(thisArg, args);

      let rawBody;
      try {
        rawBody = await readRequestBody(args);
      } catch (error) {
        this.record("bypassed", `读请求体失败：${describeError(error)}`);
        return passthrough();
      }
      if (rawBody === undefined) {
        this.record("bypassed", "请求体不是字符串");
        return passthrough();
      }

      const result = prepareRequest(rawBody);
      if (result.kind === "bypass") {
        this.record("bypassed", result.reason);
        return passthrough();
      }
      const { body, toolName, clientToolNames, streamRequested } = result;

      const response = await original.apply(thisArg, withBody(args, body));
      if (!response.ok || !response.body) {
        this.record("upstream-error", `HTTP ${response.status}`);
        return response;
      }

      try {
        const contentType = response.headers.get("content-type") ?? "";
        const { shape, response: sniffed } = await sniffResponseShape(response, contentType);

        if (shape === "json-array" && streamRequested) {
          return reframeJsonArray(sniffed, toolName, clientToolNames, (s) =>
            this.recordFromStats(s, "上游回的是 JSON 数组，已转成 SSE"),
          );
        }
        if (shape !== "sse") {
          const { response: rewritten, recovered } = await rewriteJsonResponse(
            sniffed, toolName, clientToolNames,
          );
          if (recovered !== undefined) {
            this.recordFromStats(recovered, "非流式");
          } else {
            this.record(
              "non-stream",
              streamRequested ? "请求了流式但上游没回 SSE，也没找到传输函数调用" : "本次没开流式",
            );
          }
          return rewritten;
        }
        return rewriteSseStream(sniffed, toolName, clientToolNames, (s) =>
          this.recordFromStats(s),
        );
      } catch (error) {
        // 改写失败不该毁掉整次回复：这条流放弃治疗，按原样透传太迟了
        // （流已开工），只能记录错误
        this.record("upstream-error", `改写失败：${describeError(error)}`);
        return response;
      }
    }

    recordFromStats(s, detail) {
      this.record(s.syntheticSeen ? "transported" : "plain-reply", detail, s);
    }

    record(outcome, detail, extra) {
      stats.lastOutcome = outcome;
      stats.lastDetail = detail ?? "";
      if (outcome === "transported") {
        stats.transported += 1;
        stats.missStreak = 0;
      } else if (outcome === "plain-reply") {
        stats.plainReply += 1;
        stats.missStreak += 1;
        if (stats.missStreak === CONFIG.softMissLimit) {
          toast(
            "warning",
            `连续 ${CONFIG.softMissLimit} 次没从传输函数拿到正文，这条渠道可能不支持函数调用。要关请点「${CONFIG.buttonName}」。`,
          );
        }
      } else {
        stats.other += 1;
        if (outcome === "upstream-error") stats.missStreak = 0;
      }
      if (detail || outcome !== "transported") {
        log(outcome === "transported" ? "info" : "warn",
          `${outcome}${detail ? `（${detail}）` : ""}`,
          extra?.decodedChars !== undefined ? `已还原 ${extra.decodedChars} 字` : undefined);
      }
      updateIndicator();
    }
  }

  const interceptor = new AntiTruncationInterceptor();

  // ==========================================================================
  // 状态指示牌（挂在酒馆主文档右下角，点击可开关）
  // ==========================================================================
  let indicatorEl = null;

  function getHostDocument() {
    try {
      const parentDocument = window.parent?.document;
      if (parentDocument && parentDocument !== document) return parentDocument;
    } catch { /* ignore */ }
    return document;
  }

  function ensureIndicator() {
    if (indicatorEl) return indicatorEl;
    const hostDoc = getHostDocument();
    if (!hostDoc?.body) return null;
    indicatorEl = hostDoc.createElement("div");
    indicatorEl.setAttribute("data-anti-truncation", "indicator");
    Object.assign(indicatorEl.style, {
      position: "fixed",
      bottom: CONFIG.indicator.bottom,
      right: CONFIG.indicator.right,
      zIndex: "99999",
      padding: "4px 10px",
      borderRadius: "12px",
      background: "rgba(30,30,30,0.85)",
      color: "#eee",
      font: "12px/1.6 system-ui, sans-serif",
      cursor: "pointer",
      userSelect: "none",
      whiteSpace: "nowrap",
      boxShadow: "0 1px 6px rgba(0,0,0,0.4)",
    });
    indicatorEl.addEventListener("click", toggleEnabled);
    hostDoc.body.appendChild(indicatorEl);
    updateIndicator();
    return indicatorEl;
  }

  function outcomeGlyph() {
    switch (stats.lastOutcome) {
      case "transported": return "✓";
      case "plain-reply": return "·";
      case "upstream-error": return "✗";
      case "bypassed": return "–";
      case "non-stream": return "◌";
      default: return "—";
    }
  }

  function updateIndicator() {
    if (!indicatorEl) return;
    const state = stats.enabled ? "开" : "关";
    indicatorEl.textContent =
      `🛡 ${state} ✓${stats.transported} ·${stats.plainReply} ✗${stats.other}` +
      (stats.missStreak > 0 ? ` 连失${stats.missStreak}` : "") +
      ` 上次${outcomeGlyph()}`;
    indicatorEl.style.opacity = stats.enabled ? "1" : "0.55";
  }

  // ==========================================================================
  // 开关
  // ==========================================================================
  function setEnabled(next, { silent = false } = {}) {
    stats.enabled = next;
    if (next) interceptor.ensureInstalled(); // 开启时自愈：不在 fetch 链最上层就重新挂
    interceptor.setEnabled(next);
    saveEnabled(next);
    updateIndicator();
    if (!silent) {
      toast(next ? "success" : "info", next ? "已开启" : "已关闭");
    }
  }

  function toggleEnabled() {
    setEnabled(!stats.enabled);
  }

  // ==========================================================================
  // 自检（回环测试）
  // ----------------------------------------------------------------------------
  // 不请求真实渠道：构造一个假上游，直接喂给 interceptor.intercept()。
  // 假上游会捕获"到达渠道的请求"（验证请求侧改写），并返回一条模拟
  // "模型把正文写进了传输函数"的 SSE 流（验证响应侧还原）。不消耗 token，
  // 开关状态不影响自检。
  // ==========================================================================
  const SELF_TEST_URL = "/api/backends/chat-completions/generate";
  const SELF_TEST_TEXT =
    "自检通过：正文完整经函数参数还原。\n第二行“引号”、转义\\、emoji 😀。";

  async function readResponseBody(response) {
    if (!response.body) return response.text();
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let out = "";
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      out += decoder.decode(value, { stream: true });
    }
    return out;
  }

  function parseSseForTest(text) {
    let content = "";
    let sawToolCalls = false;
    let sawDone = false;
    for (const line of text.split("\n")) {
      const match = /^data:\s?(.*)$/.exec(line);
      if (!match) continue;
      const payload = match[1].trim();
      if (payload === "[DONE]") { sawDone = true; continue; }
      try {
        const obj = JSON.parse(payload);
        const choice = obj.choices?.[0];
        if (choice?.delta?.content) content += choice.delta.content;
        if (JSON.stringify(choice ?? {}).includes("tool_calls")) sawToolCalls = true;
      } catch { /* 忽略半截行 */ }
    }
    return { content, sawToolCalls, sawDone };
  }

  /** 跑完整回环，返回逐项检查结果 */
  async function selfTest() {
    const checks = [];
    const check = (name, ok, detail = "") => checks.push({ name, ok, detail });

    // ── 静态检查：拦截器确实挂在酒馆的 fetch 上（不在最上层就先自救）──
    const remount = interceptor.ensureInstalled();
    let fetchPatched = false;
    try {
      fetchPatched = !!(interceptor.target?.fetch?.[MARKER]);
    } catch { /* ignore */ }
    let mountDetail = remount === "ok" ? "" : remount;
    if (!(interceptor.installed && fetchPatched)) {
      // 修完还不行：给出能定位原因的线索
      let reachable = false;
      let fetchType = "unknown";
      try {
        const target = window.parent ?? window;
        fetchType = typeof target.fetch;
        reachable = true;
      } catch { /* 跨域或父窗口已销毁 */ }
      mountDetail += reachable
        ? `；父窗口 fetch 类型：${fetchType}（可能被其它扩展整体替换）`
        : "；访问不到父窗口（iframe 跨域？）";
    }
    check("拦截器已挂载到酒馆 fetch", interceptor.installed && fetchPatched, mountDetail);
    check(`传输层开关当前：${stats.enabled ? "开" : "关"}`, true, "自检不依赖开关状态");

    // ── 假上游：捕获改写后的请求，回一条走了传输函数的 SSE 流 ──
    let capturedBody = null;
    const encoder = new TextEncoder();
    const mockUpstream = async (_input, init) => {
      capturedBody = typeof init?.body === "string" ? init.body : String(init?.body ?? "");
      let upstreamToolName = null;
      try {
        const parsed = JSON.parse(capturedBody);
        upstreamToolName = (parsed.tools ?? [])
          .map((t) => t?.function?.name)
          .find((n) => typeof n === "string" && n.startsWith(CONFIG.toolPrefix));
      } catch { /* ignore */ }
      const args = JSON.stringify({ content: upstreamToolName ? SELF_TEST_TEXT : "断言失败" });
      const events = [];
      events.push(`data: ${JSON.stringify({
        choices: [{ delta: { role: "assistant", tool_calls: [{ index: 0, id: "selftest", function: { name: upstreamToolName, arguments: "" } }] } }],
      })}\n\n`);
      // 参数按 3 字符碎片流式给，逼着增量解码器处理转义/代理对被切断的情况
      for (let i = 0; i < args.length; i += 3) {
        events.push(`data: ${JSON.stringify({
          choices: [{ delta: { tool_calls: [{ index: 0, function: { arguments: args.slice(i, i + 3) } }] } }],
        })}\n\n`);
      }
      events.push(`data: ${JSON.stringify({ choices: [{ delta: {}, finish_reason: "tool_calls" }] })}\n\n`);
      events.push("data: [DONE]\n\n");
      const text = events.join("");
      const parts = [];
      for (let i = 0; i < text.length; i += 7) parts.push(encoder.encode(text.slice(i, i + 7)));
      const stream = new ReadableStream({
        start(controller) { parts.forEach((p) => controller.enqueue(p)); controller.close(); },
      });
      return new Response(stream, { status: 200, headers: { "content-type": "text/event-stream" } });
    };

    // ── 跑改写链路 ──
    let response;
    try {
      response = await interceptor.intercept(mockUpstream, undefined, [
        SELF_TEST_URL,
        {
          method: "POST",
          body: JSON.stringify({
            stream: true,
            messages: [{ role: "user", content: "self test" }],
            tools: [{ type: "function", function: { name: "selftest_client_tool", parameters: { type: "object", properties: {} } } }],
          }),
        },
      ]);
    } catch (error) {
      check("改写链路执行", false, describeError(error));
      return checks;
    }
    check("改写链路执行", true);

    // ── 请求侧：上游收到的是什么 ──
    let request = null;
    try { request = JSON.parse(capturedBody ?? "null"); } catch { /* ignore */ }
    check("请求被拦截并送达上游", !!request, capturedBody === null ? "假上游没收到请求" : "");
    const injectedName = (request?.tools ?? [])
      .map((t) => t?.function?.name)
      .find((n) => typeof n === "string" && n.startsWith(CONFIG.toolPrefix));
    check("传输函数已注入请求", !!injectedName, injectedName ?? "");
    check("原有客户端工具被保留", (request?.tools ?? []).some((t) => t?.function?.name === "selftest_client_tool"));
    check("tool_choice = auto", request?.tool_choice === "auto");
    const lastMessage = request?.messages?.[request.messages.length - 1];
    check(
      "控制指令已追加到消息末尾",
      lastMessage?.role === "system" && typeof lastMessage?.content === "string" && lastMessage.content.includes(injectedName),
      `末条角色：${lastMessage?.role ?? "无"}`,
    );

    // ── 响应侧：前端收到的是什么 ──
    const text = await readResponseBody(response);
    const { content, sawToolCalls, sawDone } = parseSseForTest(text);
    check("响应正文完整还原（含换行/引号/转义/emoji）", content === SELF_TEST_TEXT, JSON.stringify(content).slice(0, 60));
    check("工具调用痕迹已抹除", !sawToolCalls);
    check("SSE 流式格式与 [DONE] 保留", sawDone && /^\s*data:/m.test(text));

    return checks;
  }

  let reportOverlay = null;
  let reportViewportSync = null;

  function closeSelfTestReport() {
    if (reportViewportSync) {
      reportViewportSync.stop();
      reportViewportSync = null;
    }
    reportOverlay?.remove();
    reportOverlay = null;
  }

  function showSelfTestReport(checks) {
    const passed = checks.filter((c) => c.ok).length;
    const allOk = passed === checks.length;
    toast(allOk ? "success" : "warning", `自检完成：${passed}/${checks.length} 项通过`);

    const hostDoc = getHostDocument();
    if (!hostDoc?.body) {
      // 没有可用的宿主文档（纯控制台环境）：降级输出
      log(allOk ? "info" : "warn", `自检 ${passed}/${checks.length} 项通过`);
      console.table?.(checks);
      return;
    }

    closeSelfTestReport();
    const overlay = hostDoc.createElement("div");
    overlay.setAttribute("data-anti-truncation", "selftest");
    Object.assign(overlay.style, {
      position: "fixed",
      left: "0", top: "0", right: "0", bottom: "0", // 基础兜底；有 visualViewport 时会被覆盖
      zIndex: "100000",
      background: "rgba(0,0,0,0.45)", display: "flex",
      // 不用 align-items:center：内容超高时居中会把上端裁到够不到的地方，
      // margin:auto 的"安全居中"超高时会自动贴顶
      justifyContent: "center",
      padding: "12px", boxSizing: "border-box",
      fontFamily: "system-ui, sans-serif",
    });
    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) closeSelfTestReport();
    });

    // 手机上布局视口（fixed/vh 参照物）和真实可见区域经常不一致（地址栏
    // 伸缩、缩放、webview 缩放模式），导致弹窗飘到屏幕上半截。用
    // visualViewport 把遮罩钉在当前真实可见区域上，并随其变化实时同步。
    const view = hostDoc.defaultView;
    const vv = view?.visualViewport;
    if (vv) {
      const sync = () => {
        Object.assign(overlay.style, {
          left: `${vv.offsetLeft}px`,
          top: `${vv.offsetTop}px`,
          width: `${vv.width}px`,
          height: `${vv.height}px`,
          right: "auto", bottom: "auto",
        });
      };
      sync();
      vv.addEventListener("resize", sync);
      vv.addEventListener("scroll", sync);
      reportViewportSync = {
        stop() {
          vv.removeEventListener("resize", sync);
          vv.removeEventListener("scroll", sync);
        },
      };
    }

    const card = hostDoc.createElement("div");
    Object.assign(card.style, {
      background: "#1e1e22", color: "#eee", borderRadius: "10px",
      padding: "14px 16px", width: "min(440px, 100%)",
      maxHeight: "80%", // 相对遮罩（已同步为可见区域），不用 vh
      margin: "auto", // 安全居中：超高时贴顶而不是上下同时裁切
      boxSizing: "border-box",
      overflowY: "auto", overscrollBehavior: "contain",
      boxShadow: "0 8px 30px rgba(0,0,0,.5)",
      fontSize: "13px", lineHeight: "1.8",
    });

    const title = hostDoc.createElement("div");
    title.textContent = `🧪 防截断自检　${passed}/${checks.length} 通过`;
    Object.assign(title.style, { fontSize: "15px", fontWeight: "600", marginBottom: "10px" });
    card.appendChild(title);

    for (const item of checks) {
      const row = hostDoc.createElement("div");
      row.textContent = `${item.ok ? "✅" : "❌"} ${item.name}${item.detail ? `（${item.detail}）` : ""}`;
      Object.assign(row.style, {
        color: item.ok ? "#d6e2f0" : "#ffb3b3",
        // 详情里带 45 字符的随机工具名，没有断行点，必须强制换行否则撑爆卡片
        wordBreak: "break-all", overflowWrap: "anywhere",
        padding: "2px 0",
      });
      card.appendChild(row);
    }

    const note = hostDoc.createElement("div");
    note.textContent = "回环自检：用假上游验证改写链路，不消耗 token。真实渠道表现看右下角指示牌的「上次」。";
    Object.assign(note.style, {
      marginTop: "10px", fontSize: "11px", color: "#999",
      wordBreak: "break-all", overflowWrap: "anywhere",
    });
    card.appendChild(note);

    const close = hostDoc.createElement("button");
    close.textContent = "关闭";
    Object.assign(close.style, {
      marginTop: "12px", padding: "8px 24px", borderRadius: "6px",
      border: "1px solid #666", background: "#333", color: "#eee",
      cursor: "pointer", fontSize: "13px", touchAction: "manipulation",
    });
    close.addEventListener("click", closeSelfTestReport);
    card.appendChild(close);

    overlay.appendChild(card);
    hostDoc.body.appendChild(overlay);
    reportOverlay = overlay;
  }

  async function runSelfTest() {
    toast("info", "自检运行中…");
    let checks;
    try {
      checks = await selfTest();
    } catch (error) {
      checks = [{ name: "自检执行", ok: false, detail: describeError(error) }];
    }
    showSelfTestReport(checks);
  }

  // ==========================================================================
  // 酒馆助手按钮
  // ==========================================================================
  function registerButton(name, handler) {
    try {
      if (typeof appendInexistentScriptButtons !== "function" || typeof getButtonEvent !== "function") {
        log("warn", "没有酒馆助手按钮 API（不是脚本环境？），用右下角指示牌开关");
        return;
      }
      appendInexistentScriptButtons([{ name, visible: true }]);
      const eventName = getButtonEvent(name);
      if (typeof eventOn === "function" && eventName) {
        eventOn(eventName, handler);
      }
      log("info", `脚本按钮已注册：${name}`);
    } catch (error) {
      log("warn", `按钮注册失败：${describeError(error)}`);
    }
  }

  // ==========================================================================
  // 启动
  // ==========================================================================
  function bootstrap() {
    stats.enabled = loadEnabled();
    interceptor.install();
    interceptor.setEnabled(stats.enabled);
    registerButton(CONFIG.buttonName, toggleEnabled);
    registerButton(CONFIG.testButtonName, runSelfTest);
    ensureIndicator();
    toast("success", `通用防截断已加载，当前：${stats.enabled ? "开" : "关"}。点「${CONFIG.buttonName}」或右下角指示牌切换。`);

    // 调试钩子：控制台里 window.__antiTruncationSelfTest() 也能跑自检
    try { window.__antiTruncationSelfTest = selfTest; } catch { /* ignore */ }

    window.addEventListener("pagehide", () => {
      interceptor.dispose();
      closeSelfTestReport();
      indicatorEl?.remove();
      indicatorEl = null;
    });
    log("info", "通用防截断传输层已启动");
  }

  try {
    bootstrap();
  } catch (error) {
    console.error(`${CONFIG.logPrefix} 启动失败`, error);
  }
})();

