            let i = 0;
            while (i < source.length) {
                const char = source[i];
                switch (this.state) {
                    case 'lookingForKey':
                        if (char === '"') {
                            this.state = 'scanKeyName';
                            this.currentKey = '';
                            this.isKeyEscaped = false;
                        }
                        i += 1;
                        break;

