                        <div class="card-tag">${item.tag}</div>
                        <div class="card-desc">${item.text}</div>
                    </li>
                `).join('');
            }
        }

        bindEvents() {
            if (this.domRefs.triggerHeader && this.domRefs.viewport) {
                this.domRefs.triggerHeader.addEventListener('click', () => {
                    this.domRefs.viewport.classList.toggle('is-folded');
                });
            }
        }
    }

    try {
        new SceneSummaryModule();
    } catch (e) {
        console.error("面板初始化失败:", e);
    }
})();
</script>
</body>
</html>

